import json
from pathlib import Path
root = Path('products/services')
for directory in sorted(root.glob('catalogue*')):
    if any(fragment in directory.name for fragment in ('one-command', 'agency-report', 'editor-handoff')):
        print(json.dumps({'directory': str(directory), 'files': [str(path.relative_to(directory)) for path in sorted(directory.rglob('*')) if path.is_file()]}, ensure_ascii=False))
